NAME = 'GerOffBiSt: Offene Bibel - Studienfassung'
BOOK = 'Amos'

CHAPTERS = {
    1: {
        1: 'Worte des Amos – der unter den Schafzüchtern von Tekoa war –, die er über Israel sah in den Tagen Usijas, dem König Judas, und in den Tagen Jerobeams, dem Sohn Joas’, dem König Israels, zwei Jahre vor dem Erdbeben.',
        2: 'Und er sprach: „ JHWH wird von Zion brüllen und von Jerusalem seine Stimme geben, dass die Weideplätze der Hirten jammern und der Gipfel des Karmel vertrocknet.“',
        3: 'So spricht JHWH: „Wegen drei Vergehen von Damaskus und wegen vier werde ich es nicht rückgängig machen (zurückbringen lassen), weil sie Gilead mit einer eisernen Dreschwalze gedroschen haben.',
        4: 'Und ich werde Feuer schicken in das Haus Hasaëls und es wird die Paläste Ben-Hadads fressen.',
        5: 'Und ich werde den Riegel von Damaskus zerbrechen und ich werde die Bewohner von Bikat-Awen ausrotten und den, der das Szepter hält, aus Bet-Eden; und das Volk von Aram wird nach Kir deportiert werden“, spricht JHWH.',
        6: 'So spricht JHWH: „Wegen drei Vergehen von Gaza und wegen vier werde ich es nicht rückgängig machen, weil sie sie alle ins Exil deportiert haben, um sie an Edom auszuliefern.',
        7: 'Und ich werde Feuer schicken an die Mauer von Gaza und es wird seine Paläste fressen.',
        8: 'Und ich werde die Bewohner von Aschdod ausrotten und den, der das Szepter hält, aus Aschkelon; und ich strecke meine Hand gegen Ekron aus und die Übriggebliebenen der Philister werden zu Grunde gehen“, spricht der Herr JHWH.',
        9: 'So spricht JHWH: „Wegen drei Vergehen von Tyrus und wegen vier werde ich es nicht rückgängig machen, weil sie sie alle an Edom [ins] Exil ausgeliefert haben und nicht des Bruderbundes gedachtet.',
        10: 'Und ich werde Feuer schicken an die Mauer von Tyrus und es wird seine Paläste fressen.“',
        11: 'So spricht JHWH: „Wegen drei Vergehen von Edom und wegen vier werde ich es nicht rückgängig machen, weil sie seinen Bruder mit dem Schwert verfolgten und sein Erbarmen zu Grunde richteten und sein Zorn zerriss für immer und sein Grimm wachte stets.',
        12: 'Und ich werde Feuer schicken nach Teman und es wird die Paläste von Bozra fressen.“',
        13: 'So spricht JHWH: „Wegen drei Vergehen der Söhne Ammons und wegen vier werde ich es nicht rückgängig machen, weil sie die Schwangeren in Gilead aufgeschlitzt haben, mit der Absicht ihre Grenzen zu erweitern.',
        14: 'Und ich werde ein Feuer anzünden an der Mauer von Rabba und es wird seine Paläste fressen im Kriegslärm am Tag der Schlacht, im Sturm am Tag des Sturmwindes.',
        15: 'Und ihr König geht ins Exil, er und seine Obersten zusammen“, spricht JHWH.',
    },
    2: {
        1: 'So spricht JHWH: Wegen drei Vergehen von Moab und wegen vier werde ich es nicht rückgängig machen, weil sie die Knochen des Königs von Edom zu Kalk zerbrannten.',
        2: 'Und ich werde Feuer schicken nach Moab und es wird die Paläste von Kerijot fressen und Moab stirbt im Getümmel, im Kriegslärm beim Ruf des Schofar.',
        3: 'Und ich werde die Richter aus ihrer Mitte vernichten und alle ihre Obersten mit ihm töten, spricht JHWH.',
        4: 'So spricht JHWH: Wegen drei Vergehen von Juda und wegen vier werde es nicht rückgängig machen, weil sie die Thora JHWHs verworfen haben und seine Ordnungen nicht hielten und ihre Lügen verführten sie, denen ihre Väter hinterher gelaufen sind.',
        5: 'Und ich werde Feuer schicken nach Juda und es wird die Paläste von Jerusalem fressen.',
        6: 'So spricht JHWH: Wegen drei Vergehen von Israel und wegen vier werde ich es nicht rückgängig machen, weil sie den Gerechten für Silber verkauft haben und den Armen für den Ertrag eines Paar Schuhe.',
        7: 'Sie treten den Kopf der Schwachen nieder auf den Staub der Erde und den Weg der Armen beugen sie und ein Mann und sein Vater gehen zu dem [selben] Mädchen um meinen heiligen Namen zu entweihen.',
        8: 'Und auf gepfändeten Kleidern strecken sie sich neben jeden Altar aus und trinken Wein von Strafgeldern im Haus ihres Gottes.',
        9: 'Und ich habe den Amoriter vor ihnen vernichtet, dessen Höhe [war] wie die Höhe der Zedern und dessen Stärke (Aussehen) [war] wie [die] der Eichen, und ich habe seine Frucht zerstört von oben und seine Wurzel von unten.',
        10: 'Und ich habe euch aus dem Land Ägypten heraufgeführt und habe euch in der Wüste vierzig Jahre geleitet um das Land des Amoriters in Besitz zu nehmen.',
        11: 'Und ich habe von euren Söhnen Propheten erweckt und von euren jungen Männern Nasiräer. Ja, war es nicht so, Söhne Israels? Ausspruch JHWH s.',
        12: 'Ihr habt die Nasiräer Wein trinken lassen und den Propheten habt ihr befohlen {folgendermaßen}: Ihr sollt nicht weissagen.',
        13: 'Siehe, ich mache es schwankend unter euch, wie der Wagen schwankt, der voll mit Heu ist.',
        14: 'Und es geht zu Grunde die Zuflucht für den Schnellen und den Starken festigt nicht seine Kraft und der Mächtige (Held) rettet nicht sein Leben (Seele).',
        15: 'Und der den Bogen Ergreifende wird nicht standhalten und der Schnellfüßige rettet [sich] nicht und der auf dem Pferd Reitende rettet nicht sein Leben (Seele).',
        16: 'Und sein starkes Herz unter den Mächtigsten (Helden) wird nackt fliehen an jenem Tag, Ausspruch JHWH s.',
    },
    3: {
        1: 'Hört dieses Wort, das gesagt hat JHWH über Euch, Söhne Israels, über das ganze Geschlecht (die ganzen Stämme), das ich aus Ägypten herausgeführt habe {folgendermaßen}:',
        2: 'Nur eurer gedachte ich von allen Geschlechtern der Erde, deswegen suche ich heim an euch alle eure Sünden.',
        3: 'Gehen zwei zusammen, ohne dass sie zusammengekommen sind?',
        4: 'Brüllt der Löwe im Gestrüpp, und hat keine Beute? Gibt ein junger Löwe seine Stimme (Laut) von seinem Lager, außer er hat [etwas] gefangen?',
        5: 'Fällt ein Vogel in die Falle [das Klappnetz] am Boden, ohne dass ein Stellholz nach (zu) ihm [geworfen wurde]? Springt die Falle [das Klappnetz] von der Erde, wenn sie nichts gefangen hat?',
        6: 'Wenn in der Stadt das Horn geblasen wird, erzittert das Volk [etwa] nicht? Geschieht etwa ein Unglück (Schlechtes/Böses) in der Stadt und JHWH hat es nicht gemacht?',
        7: 'Denn nicht macht der Herr JHWH ein Wort, außer wenn er offenbart sein Geheimnis seinen Knechten, den Propheten.',
        8: 'Der Löwe brüllt, wer fürchtet ihn nicht? Der Herr JHWH spricht, wer weissagt nicht?',
        9: 'Lasst es hören {über} den Palästen in Ashdoth und {über} den Palästen im Land Ägypten und sagt (sprecht): Versammelt euch auf den Bergen Samarias und seht die große Verwirrung (Bestürzung, Panik) in seiner Mitte und die Unterdrückung in ihrem Inneren (ihrer Mitte).',
        10: 'Und nicht verstehen sie zu tun das Rechte, Spruch JHWH s, die Aufhäufenden (sie, die anhäuften) von Gewalt und Bedrückung.',
        11: 'Deshalb, so spricht der Herr JHWH: Ein Feind (Gegner) hat das Land umzingelt (ist um das Land herum), er wirft deine Macht nieder (reißt herunter, stürzt), und deine Paläste werden geplündert.',
        12: 'So spricht JHWH: Wie errettet der Hirte aus dem Maul des Löwen zwei Unterschenkel und Ohrzipfel, so werden errettet die Söhne Israels, die sitzen in Samaria in der Ecke des Lagers und auf dem Damast des Ruhebettes.',
        13: 'hört und bezeugt dem Haus Jakobs, Spruch des Herrn JHWH, Gott der Heerscharen (Zebaot).',
        14: 'Denn (Führwahr) am Tag suche ich heim die Sünden Israels an ihm und ich suche heim auf den Altären Bet-Els und es werden zerbrechen die Hörner des Altars und zu Boden (auf die Erde) fallen.',
        15: 'Ich zerschlage (zertrümmere) dein Winterhaus zusammen mit (samt) deinem Sommerhaus und deine Elfenbeinhäuser werden zugrunde (verloren) gehen und deine vielen Häuser werden verschwinden. Spruch JHWH s.',
    },
    4: {
        4: 'Kommt nach Bet-El und vergeht euch, nach Gilgal, vergeht euch noch mehr. Und bringt eure Schlachtopfer am Morgen, am dritten Tag eure Zehnten.',
    },
    5: {
        1: 'Hört dieses Wort, das ich anhebe über euch [als] Totenklage, Haus Israel!',
        2: 'Sie ist gefallen, sie kann nicht wieder aufstehen, die Jungfrau Israel, (ist) hingeworfen auf ihren Boden, es gibt keinen, der sie aufrichtet.',
        3: 'Denn (Fürwahr) so spricht JHWH: Die Stadt, die auszieht zu tausend, wird hundert übrigbehalten. Und die auszieht zu hundert, wird zehn übrigbehalten für das Haus Israel.',
        4: 'Denn so spricht JHWH zum Haus Israel: Sucht mich, dann werdet ihr leben.',
        5: 'Und sucht nicht Bet-El auf und geht nicht nach Gilgal und geht nicht hinüber nach Beerscheba. Denn Gilgal wird ganz bestimmt gefangen wegziehen und das Haus Gottes (Bet-El) wird zum Haus des Betrugs.',
        6: 'Sucht JHWH, dann werdet ihr leben, damit er nicht das Haus Josef [wie] Feuer wirkt, das frisst und für Bet-El niemand da ist, der löscht.',
        7: 'Die Recht in Wermut verwandeln und Gerechtigkeit zu Boden werfen.',
        8: 'Der das Siebengestirn und den Orion gemacht hat, in Morgen die Finsternis verwandelt und den Tag zur Nacht verfinstert, der die Wasser des Meeres ruft und sie ausgießt über der Fläche der Erde: JHWH ist sein Name.',
        9: 'Der über dem Starken (Mächtigen) Verwüstung (Zerstörung) aufblitzen lässt und Verwüstung (Zerstörung) kommt über die Festung (befestigte Stadt).',
        10: 'Sie hassen den, der im Tor Recht spricht und verabscheuen den, der aufrichtig (untadelig) redet.',
        13: 'Darum wird der Kluge (Einsichtige) zu dieser Zeit schweigen, denn diese Zeit ist böse (schlecht).',
        14: 'Sucht das Gute und nicht das Böse, damit ihr lebt! Und JHWH, der Gott der Heerscharen, wird so mit euch sein, wie er sagt.',
        15: 'Hasst das Böse und liebt das Gute und richtet das Recht auf im Tor! Vielleicht wird JHWH, der Gott der Heerscharen, dem Überrest Josefs gnädig sein!',
        17: 'Und in allen Weinbergen ist Trauer (Wehklagen), denn ich werde durch deine Mitte schreiten, spricht JHWH.',
        18: 'Wehe denen, die den Tag JHWH s herbeiwünschen! Wozu soll denn der Tag JHWHs sein? Er wird Finsternis sein und nicht Licht.',
        20: 'Ist nicht der Tag JHWH s Finsternis (Dunkelheit) und nicht Licht? Dunkelheit, nicht Helligkeit (Glanz, Tageslicht) ist er.',
        21: 'Ich hasse, ich verwerfe eure Feste, und eure Festversammlungen kann ich nicht riechen.',
        22: 'Denn wenn ihr mir Brandopfer opfert, missfallen sie mir, und an euren Speiseopfern habe ich keinen Gefallen, und das Heilsopfer von einem Mastvieh will ich nicht ansehen.',
        23: 'Halte den Lärm deiner Lieder von mir fern! Und das Spiel deiner Harfen will ich nicht hören!',
        24: 'Aber Recht ergieße sich wie Wasser und Gerechtigkeit wie ein immerfließender Bach!',
        25: 'Habt ihr mir vierzig Jahre in der Wüste Schlachtopfer und Speiseopfer dargebracht, Haus Israel?',
        26: 'Und habt ihr den Sikkut und Kiun getragen, eure Götzenbilder, den Stern eurer Götter, die ihr euch gemacht habt?',
        27: 'So werde ich euch über Damaskus hinaus gefangen wegführen, spricht JHWH, Gott der Heerscharen ist sein Name.',
    },
    6: {
        1: 'Wehe den Sorglosen in Zion und den Sicheren auf dem Berg von Samaria, den Vornehmen des Erstlings der Völker, zu denen das Haus Israel kommt.',
        2: 'Geht hinüber nach Kalne und seht. Und geht von dort nach Hamat, der großen, und steigt hinab nach Gat, [die Stadt] der Philister. Sind sie besser als diese Königreiche, oder ist ihr Gebiet größer als euer Gebiet?',
        12: 'Rennen Pferde denn auf Felsen, oder pflügt man mit Rindern? Ihr aber verwandelt das Recht in Gift und die Furcht der Gerechtigkeit in Wermut.',
    },
    7: {
        1: 'So ließ mich der Herr JHWH sehen und siehe: einer, der Heuschrecke [n] zum Anfang als das Gras aufstieg - und siehe: das Gras nach der Heuernte des Königs.',
        2: 'Und es geschah, als sie fertig wurden, die Kräuter des Landes abzufressen, sprach ich: „Wie wird Jakob bestehen, weil er klein ist?“',
        3: 'Es tat JHWH Leid über dieses. „Es soll nicht geschehen!“, spricht JHWH.',
        4: 'So ließ mich der Herr JHWH sehen und siehe: der Herr JHWH rief zum Gericht mit dem Feuer und es fraß die große Flut und es fraß das Feld.',
        5: 'Und ich sprach: „Herr JHWH, lass doch ab! Wie wird Jakob bestehen, weil er klein ist?“',
        6: 'Es tat JHWH Leid über dieses. „Auch dies soll nicht geschehen!“, spricht der Herr JHWH.',
        7: 'So ließ er mich sehen und siehe: der Herr stellte sich auf eine senkrechte Mauer und in seiner Hand war ein Blei.',
        8: 'Und der Herr sprach zu mir: „Was siehst du, Amos?“Und ich sprach: „Ein Blei.“Und der Herr sprach: „Siehe, ich lege ein Blei an mein Volk Israel; ich werde nicht noch einmal fortfahren an ihm vorüberzugehen.',
        9: 'Und die Bamot Isaaks werden verwüstet und die Heiligtümer Israels werden verwüstet und ich werde mich erheben gegen das Haus Jerobeams mit dem Schwert.“',
        10: 'Und Amazja, der Priester von Bethel, ließ Jerobeam, dem König Israels, sagen (folgendermaßen): „Amos verschwört sich gegen dich in mitten des Hauses Israels; das Land vermag nichts zu tun gegen alle seine Worte.',
        11: "Denn so spricht Amos: 'Durch das Schwert wird Jerobeam sterben und Israel wird bestimmt aus seinem Land deportiert werden.'“",
        12: 'Und Amazja sprach zu Amos: „Prophet, gehe, fliehe zu dir in das Land Juda und iss dort Brot und weissage dort.',
        13: 'Und in Bethel fahre nicht fort weiter weiszusagen, denn es ist das Heiligtum des Königs und das Haus des Königreiches ist es.“',
        14: 'Und Amos antwortete und sprach zu Amazja: „Ich bin kein Prophet und ich bin kein Prophetensohn, denn ich bin ein Hirte und ein Maulbeerfeigenbaumzüchter bin ich.“',
        15: 'Und JHWH nahm mich aus der Herde und JHWH sprach zu mir: „Gehe, weissage meinem Volk Israel!“',
        16: "Und nun höre das Wort JHWH s: „Du sprichst: 'Du sollst nicht weissagen über Israel und du sollst nicht weissagen über das Haus Isaak!'“",
        17: 'Deshalb, so spricht JHWH: „Deine Frau wird in der Stadt zur Hure werden und deine Söhne und deine Töchter werden durch das Schwert fallen und dein Land wird mit der Messschnur verteilt werden und du wirst auf unreinem Land sterben und Israel wird gewiss von seinem Land deportiert werden.“',
    },
    8: {
        1: 'So ließ mich der Herr JHWH sehen und siehe: ein Korb [mit] Sommerfrüchten.',
        2: 'Und er sprach: „Was siehst du, Amos?“Und ich sprach: „Ein Korb [mit] Sommerfrüchten.“Und JHWH sprach zu mir: „Das Ende ist gekommen für mein Volk Israel; ich werde nicht noch einmal fortfahren an ihm vorüberzugehen.',
        3: 'Und die Lieder des Tempels werden zu Wehklagen an jenem Tag,“Ausspruch des Herrn JHWH. „An allen Orten werfen sie schweigend viele Leichen.“',
        4: 'Hört dieses, die ihr den Armen zermalmt, und des Armen Land ein Ende macht;',
        5: 'um zu sagen: „Wann ist der Neumond vorübergegangen, dass wir das Getreide verkaufen, und der Sabbat, dass wir das Korn öffnen um das Efa zu verkleinern und um den Schekel zu vergrößern und eine falsche Waage zu beugen;',
        6: 'um mit Silber die Schwachen zu kaufen und den Armen mit dem Ertrag eines Paar Schuhe und die Spreu des Korns verkaufen.“',
        7: 'JHWH schwört beim Stolz Jakobs: „Wenn ich nicht für immer alle ihre Taten vergesse!',
        8: 'Erbebt über diesen nicht die Erde und jammern alle, die auf ihr wohnen und völlig hinaufgehen wie der Fluss und aufwallen und sinken wie der Strom Ägyptens?',
        9: 'Und es geschieht an jenem Tag, Ausspruch des Herrn JHWH, und ich werde die Sonne am Mittag untergehen lassen und verfinstern die Erde am hellen Tag.',
        10: 'Und ich werde umkehren eure Feste in Trauer und alle eure Lieder in Wehklagen; und ich werde auf alle Hüften einen Sack bringen und auf alle Köpfe eine Glatze; und ich werde es machen wie die Trauer um den einzigen Sohn und ihr Ende wie einen bitteren Tag.',
        11: 'Siehe, Tage kommen“, Ausspruch des Herrn JHWH, „dass ich Hunger über das Land schicken werde, nicht Hunger nach Brot und nicht Durst nach Wasser, sondern um zu hören das Wort JHWH s.',
        12: 'Und sie wanken von Meer zu Meer und vom Norden und bis zum Osten; sie werden umherschweifen um das Wort JHWH s zu suchen und werden es nicht finden.',
        13: 'An jenem Tag werde die schönen Jungfrauen und die jungen Männer vor Durst ohnmächtig dahinsinken.',
        14: "Die bei der Schuld Samarias schwören und sprechen: 'So wahr dein Gott lebt, Dan! Und so wahr der Weg nach Beerscheba lebt!' Und sie werden fallen und nicht wieder aufstehen.“",
    },
    9: {
        1: 'Ich sah den Herrn auf dem Altar stehen und er sprach: Schlage auf das Kapitel, dass die Schwellen erschüttert werden und zerbrich sie ihnen allen auf dem Kopf. Und die Übriggebliebenen werde ich mit dem Schwert töten; kein Flüchtling flieht vor ihnen und kein Entkommener rettet sich vor ihnen.',
        2: 'Wenn sie in den Scheol einbrechen, wird meine Hand sie von dort nehmen; und wenn sie zum Himmel hinaufgehen, werde ich sie von dort hinunternehmen.',
        3: 'Und wenn sie sich auf dem Gipfel des Karmel verbergen, werde ich von dort suchen und sie nehmen; und wenn sie sich verstecken vor meinen Augen auf dem Grund des Meeres, werde ich von dort der Schlange befehlen und sie wird sie beißen.',
        4: 'Und wenn sie in die Gefangenschaft gehen vor den Augen ihrer Feinde, werde ich von dort dem Schwert befehlen und es wird sie töten; und ich werde meine Augen auf sie legen - zum Bösen und nicht zum Guten.',
        5: 'Und der Herr, JHWH der Heerscharen (Zebaot), schlägt auf das Land und es schwankt und alle, die auf ihm sitzen, werden jammern, dass es hinaufgeht wie der Fluss und zurückgeht wie der Strom Ägyptens.',
        6: 'Er baut im Himmel seine Stufe (Obergemach, Söller) und seine Himmelsgewölbe auf der Erde gründet er. Er ruft die Wasser des Meeres und er gießt sie aus auf dem Angesicht der Erde, JHWH ist sein Name.',
        7: 'Seid ihr nicht wie die Söhne der Kuschiter für mich, ihr Söhne Israels, sricht JHWH. Habe nicht ich Israel herausgefährt aus dem Land Ägypten und die Philister aus Kaftor und die Aramäer aus Kir.',
        8: 'Siehe, die Augen des Herrn JHWH sind auf dem sündigen Königreich, und ich vernichte es (rotte es aus) vom Angesicht der Erde. Nur, dass ich nicht völlig (vollständig) vernichte (ausrotte) das Haus Jakobs, spricht JHWH.',
        9: 'Denn siehe, ich will befehlen und will schütteln in alle Völker das Haus Israels, wie man schüttelt mit einem Sieb und nicht fällt ein Stein auf die (zur) Erde.',
        10: 'Mit dem Schwert werden getötet alle Sünder meines Volkes, die sagen: Du führst nicht herbei und lässt nicht zu uns kommen das Böse (Unheil).',
        11: 'An diesem Tag will ich [wieder] aufstellen die Hütte Davids, die umgefallene (verfallene, eingestürzte). Und ich (ver) mauere ihre Risse und ihr Niedergerissenes (Abgebrochenes, ihre Trümmer) stelle ich auf und erbaue sie wieder wie in den Tagen der der Vorzeit.',
        12: 'Damit sie in Besitz nehmen das Übrige (den Rest) von Edom und alle (Fremd) völker, über die ausgerufen (genannt) ist mein Namen, spricht der JHWH, der dies tut.',
        13: 'Siehe, Tage kommen, spricht JHWH, da nähert sich (tritt heran) der Pflüger dem Schnitter und der Weintraubentreter an den Samensäer und sie werden herabtriefen lassen Most von den Bergen und alle Hügel zwerfließen.',
        14: 'Ich wende das Geschick meines Volkes Israel. Sie werden aufbauen ihre verwüsteten Städte und sie bewohnen und sie pflanzen Weinberge und trinken ihren (deren) Wein und sie machen Gärten und essen ihre Früchte.',
        15: 'Und ich pflanze sie in auf ihr Land (ihren Erdboden, ihre Erde). Und sie sollen nicht mehr vertrieben (herausgerissen) werden von iherem Land (ihrem Erdboden, ihrer Erde) die ich ihnen gegeben habe, spricht (sagt) JHWH, dein Gott.',
    },
}
